  "transcript": {
    "segments": [
      {
        "start": 0,
        "end": 2.82,
        "text": "这个金融开员工具,彭博社的桌子给先了"
      },
      {
        "start": 2.82,
        "end": 5.72,
        "text": "直接把花儿街都用的彭博社中端直接开员"
      },
      {
        "start": 5.72,
        "end": 8.4,
        "text": "要知道彭博社中端一年差不多20多万"
      },
      {
        "start": 8.4,
        "end": 10.36,
        "text": "现在直接开员免费简直夸张"
      },
      {
        "start": 10.36,
        "end": 12.7,
        "text": "它的功能非常全面从实实行金流"
      },
      {
        "start": 12.7,
        "end": 15.68,
        "text": "黑线到基本涵盖全部交易种类"
      },
      {
        "start": 15.68,
        "end": 17.04,
        "text": "外汇加密货币等"
      },
      {
        "start": 17.04,
        "end": 19.4,
        "text": "而且还内置了37个AI智能体"
      },
      {
        "start": 19.4,
        "end": 21.76,
        "text": "从传奇的巴菲特、芒格等人"
      },
      {
        "start": 21.76,
        "end": 23.96,
        "text": "到皮特临旗都同同涵盖"
      },
      {
        "start": 23.96,
        "end": 26.24,
        "text": "还有一个我觉得最有想象力的功能"
      },
      {
        "start": 26.24,
        "end": 28.08,
        "text": "它内置节点编辑器"
      },
      {
        "start": 28.08,
        "end": 29.44,
        "text": "直接拖业就行"
      },
      {
        "start": 29.44,
        "end": 31.76,
        "text": "把抓数据计算AI分析生成报告"
      },
      {
        "start": 31.76,
        "end": 34.28,
        "text": "串成一条自动化流水线不用写一行代"
      },
      {
        "start": 34.28,
        "end": 35.64,
        "text": "它还集成了MCP接口"
      },
      {
        "start": 35.64,
        "end": 38.68,
        "text": "可以把金融分析能力直接接近KL的Codex"
      },
      {
        "start": 38.68,
        "end": 40.04,
        "text": "这类AI工具理用"
      },
      {
        "start": 40.04,
        "end": 42.08,
        "text": "而且极其了100多个数据员"
      },
      {
        "start": 42.08,
        "end": 44.32,
        "text": "让你在模拟盘里实实跑策略"
      },
      {
        "start": 44.32,
        "end": 45.64,
        "text": "都完全没问题"
      },
      {
        "start": 45.64,
        "end": 48.44,
        "text": "得益于它用C家加重写的原生桌面应用"
      },
      {
        "start": 48.44,
        "end": 49.68,
        "text": "拍审做分析引擎"
      },
      {
        "start": 49.68,
        "end": 51.16,
        "text": "编议出来就是一个文件"
      },
      {
        "start": 51.16,
        "end": 52,
        "text": "双机就跑"
      },
      {
        "start": 52,
        "end": 52.6,
        "text": "启动快"
      },
      {
        "start": 52.6,
        "end": 52.96,
        "text": "不卡"
      },
      {
        "start": 52.96,
        "end": 53.8,
        "text": "几乎不吃内存"
      },
      {
        "start": 53.8,
        "end": 54.6,
        "text": "支持Windows"
      },
      {
        "start": 54.6,
        "end": 55.6,
        "text": "MacOS"
      },
      {
        "start": 55.6,
        "end": 56.88,
        "text": "Link是全平台"
      },
      {
        "start": 56.88,
        "end": 58.6,
        "text": "感兴趣的朋友可以试试了"
      }
